# Let me try a smarter approach: build a bipartite graph with girth >= 8
# (which implies girth >= 7) and at least 33 edges
# Bipartite graphs are 2-colorable, hence 3-colorable

import random
from collections import deque

def build_adj(edges, n=24):
    adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)
    return adj

def check_girth_bfs(adj, min_girth=7):
    n = len(adj)
    for start in range(n):
        dist = [-1] * n
        parent = [-1] * n
        dist[start] = 0
        queue = deque([start])

        while queue:
            u = queue.popleft()
            for v in adj[u]:
                if dist[v] == -1:
                    dist[v] = dist[u] + 1
                    parent[v] = u
                    queue.append(v)
                elif v != parent[u]:
                    cycle_len = dist[u] + dist[v] + 1
                    if cycle_len < min_girth:
                        return False, cycle_len
    return True, None

def check_3_colorable(adj):
    n = len(adj)
    color = [-1] * n

    def backtrack(v):
        if v == n:
            return True
        for c in range(3):
            valid = True
            for u in adj[v]:
                if color[u] == c:
                    valid = False
                    break
            if valid:
                color[v] = c
                if backtrack(v + 1):
                    return True
                color[v] = -1
        return False

    return backtrack(0)

