random.seed(123)

def try_bipartite():
    n = 24
    # Split into two equal parts
    A = list(range(12))
    B = list(range(12, 24))

    # Start with a spanning tree
    edges = set()
    # Connect A[0] to B[0], then build a tree
    edges.add((0, 12))
    for i in range(1, 12):
        edges.add((0, 12 + i))  # Connect A[0] to all of B
    for i in range(1, 12):
        edges.add((i, 12))  # Connect all of A to B[0]

    # Now try to add more edges
    attempts = 0
    while len(edges) < 33 and attempts < 50000:
        u = random.choice(A)
        v = random.choice(B)
        if (u, v) in edges:
            attempts += 1
            continue

        test_edges = edges | {(u, v)}
        adj = build_adj(test_edges)
        girth_ok, _ = check_girth_bfs(adj, 7)

        if girth_ok:
            edges.add((u, v))
        attempts += 1

    return list(edges)

